@charset "UTF-8";
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400&family=Noto+Serif+JP:wght@300;400;500;600&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap');

/* ==========================================================================
   CSS Variables & Global Reset
   ========================================================================== */
:root {
  /* Color Palette - Elegant Warm Espresso & Ecrù */
  --color-bg-main: #fbf9f5;
  --color-bg-alt: #f4efe6;
  --color-bg-card: #ffffff;
  --color-bg-dark: #1e1916;
  --color-surface-hover: #f0e9dc;

  --color-text-primary: #27221e;
  --color-text-secondary: #5e554d;
  --color-text-muted: #8c8278;
  --color-text-light: #f7f4ee;

  --color-accent-amber: #b9854b;
  --color-accent-light: #d8ab79;
  --color-accent-hover: #9c6c39;
  --color-accent-soft: rgba(185, 133, 75, 0.12);
  --color-accent-red: #e54d2e;

  --color-border: #e6dfd5;
  --color-border-dark: rgba(255, 255, 255, 0.12);

  /* Typography */
  --font-serif: 'Cormorant Garamond', 'Noto Serif JP', serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;

  /* Elevation & Shadows */
  --shadow-sm: 0 2px 6px rgba(39, 34, 30, 0.05);
  --shadow-md: 0 6px 18px rgba(39, 34, 30, 0.08);
  --shadow-lg: 0 16px 36px rgba(39, 34, 30, 0.12);
  --shadow-dark: 0 20px 40px rgba(0, 0, 0, 0.35);

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-smooth: 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg-main);
  color: var(--color-text-primary);
  line-height: 1.7;
  overflow-x: hidden;
}

body.modal-open {
  overflow: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  cursor: pointer;
  border: none;
  background: transparent;
  font-family: inherit;
  color: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

/* ==========================================================================
   Base Layout & App Container
   ========================================================================== */
.cafe-app {
  min-height: 100vh;
  position: relative;
  display: flex;
  flex-direction: column;
}

.section {
  padding: 6rem 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

@media (min-width: 768px) {
  .section {
    padding: 8rem 2rem;
  }
}

.section-anchor {
  scroll-margin-top: 5rem;
}

/* Section Header Typography */
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3.5rem;
}

.section-en {
  display: inline-block;
  font-family: var(--font-serif);
  font-size: 0.95rem;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: var(--color-accent-amber);
  margin-bottom: 0.5rem;
  font-weight: 600;
}

.section-title {
  font-family: var(--font-serif);
  font-size: 2.2rem;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: 1.35;
  margin-bottom: 1rem;
  letter-spacing: 0.05em;
}

@media (min-width: 768px) {
  .section-title {
    font-size: 2.75rem;
  }
}

.section-lead {
  font-size: 1rem;
  color: var(--color-text-secondary);
  line-height: 1.8;
}

/* Common Buttons */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2rem;
  background-color: var(--color-accent-amber);
  color: #ffffff;
  border-radius: var(--radius-full);
  font-weight: 500;
  letter-spacing: 0.06em;
  font-size: 0.95rem;
  transition: background-color var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  box-shadow: 0 4px 14px rgba(185, 133, 75, 0.28);
}

.btn-primary:hover {
  background-color: var(--color-accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(185, 133, 75, 0.38);
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 2rem;
  background-color: transparent;
  color: var(--color-text-primary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-full);
  font-weight: 500;
  letter-spacing: 0.06em;
  font-size: 0.95rem;
  transition: all var(--transition-fast);
}

.btn-outline:hover {
  border-color: var(--color-text-primary);
  background-color: rgba(39, 34, 30, 0.04);
  transform: translateY(-2px);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.6rem;
  background-color: var(--color-bg-alt);
  color: var(--color-text-primary);
  border-radius: var(--radius-full);
  font-size: 0.9rem;
  font-weight: 500;
  transition: background-color var(--transition-fast);
}

.btn-secondary:hover {
  background-color: var(--color-surface-hover);
}

/* ==========================================================================
   Navbar
   ========================================================================== */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 900;
  background: rgba(251, 249, 245, 0.88);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(230, 223, 213, 0.8);
  transition: background var(--transition-smooth), box-shadow var(--transition-smooth);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--color-text-primary);
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.nav-logo span {
  font-size: 0.65rem;
  font-family: var(--font-sans);
  letter-spacing: 0.2em;
  color: var(--color-accent-amber);
  margin-top: 2px;
}

.nav-links {
  display: none;
  list-style: none;
  gap: 2.25rem;
  align-items: center;
}

@media (min-width: 860px) {
  .nav-links {
    display: flex;
  }
}

.nav-links a {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
  position: relative;
  letter-spacing: 0.04em;
}

.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1.5px;
  background-color: var(--color-accent-amber);
  transition: width var(--transition-smooth);
}

.nav-links a:hover {
  color: var(--color-accent-amber);
}

.nav-links a:hover::after {
  width: 100%;
}

.nav-btn {
  display: none;
}

@media (min-width: 860px) {
  .nav-btn {
    display: inline-flex;
    padding: 0.65rem 1.4rem;
    font-size: 0.85rem;
  }
}

.mobile-menu-btn {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  background: transparent;
  gap: 6px;
  z-index: 1000;
}

@media (min-width: 860px) {
  .mobile-menu-btn {
    display: none;
  }
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--color-text-primary);
  border-radius: 2px;
  transition: transform var(--transition-smooth), opacity var(--transition-smooth);
}

/* Mobile Nav Drawer */
.mobile-nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  background: var(--color-bg-main);
  z-index: 850;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 2rem;
  gap: 2rem;
  transform: translateY(-100%);
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: var(--shadow-lg);
}

.mobile-nav.open {
  transform: translateY(0);
}

.mobile-nav a {
  font-family: var(--font-serif);
  font-size: 1.6rem;
  color: var(--color-text-primary);
  letter-spacing: 0.05em;
  transition: color var(--transition-fast);
}

.mobile-nav a:hover {
  color: var(--color-accent-amber);
}

/* ==========================================================================
   Hero Section
   ========================================================================== */
.hero-section {
  position: relative;
  min-height: 90vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8rem 1.5rem 5rem;
  background-image: url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?q=80&w=1600&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
  color: #ffffff;
  overflow: hidden;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(22, 18, 15, 0.55) 0%,
    rgba(22, 18, 15, 0.72) 60%,
    rgba(22, 18, 15, 0.88) 100%
  );
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.hero-badge {
  display: inline-block;
  padding: 0.4rem 1.25rem;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.25);
  backdrop-filter: blur(6px);
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--color-accent-light);
  margin-bottom: 1.5rem;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: 2.8rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.06em;
  margin-bottom: 1.5rem;
  text-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
}

@media (min-width: 768px) {
  .hero-title {
    font-size: 4.2rem;
  }
}

.hero-subtitle {
  font-size: 1.05rem;
  line-height: 1.9;
  color: rgba(255, 255, 255, 0.88);
  max-width: 620px;
  margin: 0 auto 2.5rem;
  font-weight: 300;
}

@media (min-width: 768px) {
  .hero-subtitle {
    font-size: 1.15rem;
  }
}

.hero-actions {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  justify-content: center;
  align-items: center;
}

@media (min-width: 480px) {
  .hero-actions {
    flex-direction: row;
    gap: 1.25rem;
  }
}

.hero-actions .btn-outline {
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.45);
}

.hero-actions .btn-outline:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: #ffffff;
}

/* ==========================================================================
   Concept Section
   ========================================================================== */
.concept-section {
  background-color: var(--color-bg-main);
}

.concept-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3rem;
  margin-top: 2rem;
}

@media (min-width: 860px) {
  .concept-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 2.5rem;
  }
}

.concept-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
  display: flex;
  flex-direction: column;
}

.concept-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
}

.concept-img {
  width: 100%;
  height: 240px;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.concept-card:hover .concept-img {
  transform: scale(1.04);
}

.concept-card > div:first-child {
  overflow: hidden;
}

.concept-text {
  padding: 2rem 1.75rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.concept-text h3 {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  margin-bottom: 0.75rem;
  color: var(--color-text-primary);
  font-weight: 600;
}

.concept-text p {
  font-size: 0.95rem;
  color: var(--color-text-secondary);
  line-height: 1.8;
}

/* ==========================================================================
   Menu Section
   ========================================================================== */
.menu-section {
  background-color: var(--color-bg-alt);
}

.menu-filters {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 3rem;
}

.filter-tab {
  padding: 0.6rem 1.4rem;
  font-size: 0.92rem;
  border-radius: var(--radius-full);
  background: var(--color-bg-card);
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border);
  font-weight: 500;
  transition: all var(--transition-fast);
}

.filter-tab:hover {
  color: var(--color-accent-amber);
  border-color: var(--color-accent-amber);
}

.filter-tab.active {
  background-color: var(--color-text-primary);
  color: #ffffff;
  border-color: var(--color-text-primary);
  box-shadow: var(--shadow-sm);
}

.menu-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 640px) {
  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .menu-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.menu-card {
  background: var(--color-bg-card);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-smooth), box-shadow var(--transition-smooth);
  position: relative;
}

.menu-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.menu-img-wrap {
  position: relative;
  width: 100%;
  padding-top: 66.66%; /* 3:2 Aspect Ratio */
  overflow: hidden;
  background-color: var(--color-surface-hover);
}

.menu-img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s ease;
}

.menu-card:hover .menu-img {
  transform: scale(1.05);
}

.menu-tag-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  padding: 0.3rem 0.75rem;
  background: rgba(39, 34, 30, 0.85);
  color: #ffffff;
  backdrop-filter: blur(4px);
  font-size: 0.75rem;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
  font-weight: 500;
  z-index: 2;
}

.menu-info {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.menu-header-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.5rem;
}

.menu-name {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: 1.3;
}

.menu-kana {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  display: block;
  margin-top: 2px;
}

.menu-price {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent-amber);
  white-space: nowrap;
  margin-left: 0.75rem;
}

.menu-desc {
  font-size: 0.88rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 1.25rem;
  flex: 1;
}

.menu-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 1.25rem;
}

.menu-tag {
  font-size: 0.72rem;
  padding: 0.2rem 0.55rem;
  background-color: var(--color-bg-alt);
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
}

.menu-footer-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid var(--color-border);
  padding-top: 1rem;
  margin-top: auto;
}

.favorite-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), transform var(--transition-fast);
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-sm);
}

.favorite-btn:hover {
  color: var(--color-accent-red);
}

.favorite-btn.active {
  color: var(--color-accent-red);
  font-weight: 600;
}

.menu-detail-btn {
  font-size: 0.85rem;
  color: var(--color-accent-amber);
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: color var(--transition-fast);
}

.menu-detail-btn:hover {
  color: var(--color-accent-hover);
  text-decoration: underline;
}

/* ==========================================================================
   Access & Location Section
   ========================================================================== */
.access-section {
  background-color: var(--color-bg-main);
}

.access-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2.5rem;
  align-items: stretch;
}

@media (min-width: 900px) {
  .access-grid {
    grid-template-columns: 1.1fr 1fr;
    gap: 3.5rem;
  }
}

.access-info-card {
  background: var(--color-bg-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.info-row {
  display: flex;
  padding: 1.1rem 0;
  border-bottom: 1px solid var(--color-border);
  font-size: 0.95rem;
}

.info-row:last-child {
  border-bottom: none;
}

.info-label {
  width: 110px;
  font-weight: 600;
  color: var(--color-text-primary);
  flex-shrink: 0;
}

.info-value {
  color: var(--color-text-secondary);
  line-height: 1.6;
  flex: 1;
}

/* Map Mock UI */
.map-mock {
  position: relative;
  min-height: 380px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background-color: #e5e3df;
  background-image: 
    radial-gradient(#cfcac2 1px, transparent 1px),
    linear-gradient(to right, rgba(200, 195, 185, 0.3) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(200, 195, 185, 0.3) 1px, transparent 1px);
  background-size: 20px 20px, 60px 60px, 60px 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
}

.map-pin {
  position: relative;
  width: 44px;
  height: 44px;
  background: var(--color-accent-amber);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
  animation: bounce 2s infinite ease-in-out;
}

.map-pin::after {
  content: '';
  width: 16px;
  height: 16px;
  background: #ffffff;
  border-radius: 50%;
  transform: rotate(45deg);
}

@keyframes bounce {
  0%, 100% {
    transform: translateY(0) rotate(-45deg);
  }
  50% {
    transform: translateY(-8px) rotate(-45deg);
  }
}

.map-overlay-card {
  position: absolute;
  bottom: 20px;
  left: 20px;
  right: 20px;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(8px);
  padding: 1.25rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border);
}

.map-overlay-card h4 {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.map-overlay-card p {
  font-size: 0.85rem;
  color: var(--color-text-secondary);
}

/* ==========================================================================
   Reserve Banner
   ========================================================================== */
.reserve-banner {
  background: linear-gradient(135deg, #2b2420 0%, #1a1614 100%);
  color: #ffffff;
  padding: 5rem 1.5rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.reserve-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(185, 133, 75, 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.reserve-banner h2 {
  font-family: var(--font-serif);
  font-size: 2.4rem;
  font-weight: 600;
  margin-bottom: 1rem;
  letter-spacing: 0.05em;
}

.reserve-banner p {
  color: rgba(255, 255, 255, 0.8);
  max-width: 600px;
  margin: 0 auto 2.25rem;
