import { useState, useEffect } from 'react';
import { MenuCategory, MenuItem } from '../types';
import { menuCategories, menuItems } from '../data/cafeData';

interface MenuSectionProps {
  onOpenReserve?: () => void;
}

const FAVORITES_STORAGE_KEY = 'cafe_etoile_favorites';

const MenuSection = ({ onOpenReserve }: MenuSectionProps) => {
  const [activeCategory, setActiveCategory] = useState<MenuCategory>('all');
  const [favorites, setFavorites] = useState<Record<string, boolean>>(() => {
    try {
      const stored = localStorage.getItem(FAVORITES_STORAGE_KEY);
      return stored ? JSON.parse(stored) : {};
    } catch {
      return {};
    }
  });
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);

  useEffect(() => {
    try {
      localStorage.setItem(FAVORITES_STORAGE_KEY, JSON.stringify(favorites));
    } catch {
      // localStorageの利用不可時は何もしない
    }
  }, [favorites]);

  const handleToggleFavorite = (id: string) => {
    setFavorites((prev) => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  const filteredItems = activeCategory === 'all'
    ? menuItems
    : menuItems.filter((item) => item.category === activeCategory);

  return (
    <section id="menu" className="section menu-section">
      <div className="section-header">
        <span className="section-en">Seasonal & Standard</span>
        <h2 className="section-title">自慢の珈琲と手作りベイク</h2>
        <p className="section-lead">
          厳選したスペシャルティコーヒー豆と、毎朝焼き上げる自家製スイーツ＆ブレッド。
          素材と製法に妥協せず仕上げたこだわりのラインナップです。
        </p>
      </div>

      {/* カテゴリ切り替えフィルター */}
      <div className="menu-filters" role="tablist" aria-label="メニューカテゴリー">
        {menuCategories.map((cat) => {
          const isActive = activeCategory === cat.key;
          return (
            <button
              key={cat.key}
              type="button"
              role="tab"
              aria-selected={isActive}
              className={isActive ? 'filter-tab active' : 'filter-tab'}
              onClick={() => setActiveCategory(cat.key)}
            >
              {cat.label}
            </button>
          );
        })}
      </div>

      {/* メニューグリッド */}
      <div className="menu-grid">
        {filteredItems.map((item) => {
          const isFav = !!favorites[item.id];
          return (
            <article key={item.id} className="menu-card">
              <div className="menu-img-wrap">
                <img
                  src={item.image}
                  alt={item.name}
                  loading="lazy"
                  className="menu-img"
                />
                {item.seasonal ? (
                  <span className="menu-tag-badge">季節限定</span>
                ) : item.isRecommended ? (
                  <span className="menu-tag-badge">おすすめ</span>
                ) : null}
              </div>

              <div className="menu-info">
                <div className="menu-header-row">
                  <div>
                    <h3 className="menu-name">{item.name}</h3>
                    <span className="menu-kana">{item.kana}</span>
                  </div>
                  <span className="menu-price">¥{item.price.toLocaleString()}</span>
                </div>

                <p className="menu-desc">{item.description}</p>

                <div className="menu-tags">
                  {item.tags.map((tag, idx) => (
                    <span key={idx} className="menu-tag">
                      #{tag}
                    </span>
                  ))}
                </div>

                <div className="menu-footer-row">
                  <button
                    type="button"
                    className={isFav ? 'favorite-btn active' : 'favorite-btn'}
                    onClick={() => handleToggleFavorite(item.id)}
                    aria-label={`${item.name}をお気に入り登録`}
                  >
                    <span>{isFav ? '♥ お気に入り' : '♡ 気になる'}</span>
                  </button>

                  <button
                    type="button"
                    className="menu-detail-btn"
                    onClick={() => setSelectedItem(item)}
                  >
                    詳しく見る →
                  </button>
                </div>
              </div>
            </article>
          );
        })}
      </div>

      {/* メニュー詳細モーダル */}
      {selectedItem && (
        <div
          className="modal-backdrop"
          onClick={() => setSelectedItem(null)}
          role="dialog"
          aria-modal="true"
          aria-labelledby="menu-modal-title"
        >
          <div
            className="modal-container"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-header">
              <h3 id="menu-modal-title">{selectedItem.name}</h3>
              <button
                type="button"
                className="modal-close"
                onClick={() => setSelectedItem(null)}
                aria-label="閉じる"
              >
                ✕
              </button>
            </div>

            <div className="modal-body">
              <img
                src={selectedItem.image}
                alt={selectedItem.name}
                className="detail-img"
              />

              <div className="menu-header-row">
                <div>
                  <span className="menu-kana">{selectedItem.kana}</span>
                  <div className="menu-tags">
                    <span className="menu-tag">
                      {menuCategories.find((c) => c.key === selectedItem.category)?.label || ''}
                    </span>
                    {selectedItem.tags.map((tag, i) => (
                      <span key={i} className="menu-tag">#{tag}</span>
                    ))}
                  </div>
                </div>
                <span className="menu-price">¥{selectedItem.price.toLocaleString()}</span>
              </div>

              <p className="menu-desc">
                {selectedItem.description}
              </p>

              <div className="detail-specs">
                <div><strong>提供時間:</strong> 終日ご提供（モーニング・カフェタイム）</div>
                <div><strong>アレルギー特定原材料等:</strong> 小麦、乳、卵（品目により異なります）</div>
                <div><strong>お持ち帰り:</strong> 一部ドリンクおよび焼き菓子はテイクアウト対応可能</div>
              </div>

              <div className="menu-footer-row">
                {onOpenReserve && (
                  <button
                    type="button"
                    className="btn-primary"
                    onClick={() => {
                      setSelectedItem(null);
                      onOpenReserve();
                    }}
                  >
                    このメニューを目当てに予約
                  </button>
                )}
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={() => setSelectedItem(null)}
                >
                  閉じる
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default MenuSection;

import { useState, useEffect } from 'react';
import { ReservationFormValues } from '../types';

interface ReservationModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const initialFormValues: ReservationFormValues = {
  name: '',
  tel: '',
  email: '',
  date: '',
  time: '14:00',
  guests: 2,
  seatingPreference: 'table',
  note: ''
};

const ReservationModal = ({ isOpen, onClose }: ReservationModalProps) => {
  const [formValues, setFormValues] = useState<ReservationFormValues>(initialFormValues);
  const [isSubmitted, setIsSubmitted] = useState<boolean>(false);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      document.body.style.overflow = originalOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen) {
    return null;
  }

  const today = new Date().toISOString().split('T')[0];

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => {
    const { name, value } = e.target;
    setFormValues((prev) => ({
      ...prev,
      [name]: name === 'guests' ? Number(value) : value
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formValues.name || !formValues.tel || !formValues.date) {
      return;
    }
    setIsSubmitted(true);
  };

  const handleResetAndClose = () => {
    setIsSubmitted(false);
    setFormValues(initialFormValues);
    onClose();
  };

  const getSeatingLabel = (pref: ReservationFormValues['seatingPreference']) => {
    switch (pref) {
      case 'counter':
        return 'カウンター席（バリスタの手元を楽しめるお席）';
      case 'table':
        return 'テーブル席（ゆったりくつろげるソファー席）';
      case 'terrace':
        return 'テラス席（自然の風を感じるペット同伴可能エリア）';
      default:
        return '';
    }
  };

  return (
    <div
      className="modal-backdrop"
      onClick={handleResetAndClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby="reserve-modal-title"
    >
      <div
        className="modal-container reservation-modal"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-header">
          <h3 id="reserve-modal-title">
            {isSubmitted ? 'ご予約リクエスト受付完了' : '席のご予約リクエスト'}
          </h3>
          <button
            type="button"
            className="modal-close"
            onClick={handleResetAndClose}
            aria-label="閉じる"
          >
            ✕
          </button>
        </div>

        <div className="modal-body">
          {isSubmitted ? (
            <div className="reserve-success">
              <h4>ご予約リクエストを承りました</h4>
              <p>
                {formValues.name} 様、CAFÉ ÉTOILE をお選びいただきありがとうございます。<br />
                ご指定いただいた内容をもとに空席状況を確認し、24時間以内に当店担当者より
                お電話またはメールにて確定のご連絡を差し上げます。
              </p>

              <div className="detail-specs">
                <div><strong>来店日時:</strong> {formValues.date} {formValues.time}</div>
                <div><strong>人数:</strong> {formValues.guests}名様</div>
                <div><strong>希望のお席:</strong> {getSeatingLabel(formValues.seatingPreference)}</div>
                <div><strong>ご連絡先:</strong> {formValues.tel} ({formValues.email})</div>
                {formValues.note && (
                  <div><strong>ご要望・アレルギー:</strong> {formValues.note}</div>
                )}
              </div>

              <button
                type="button"
                className="btn-primary"
                onClick={handleResetAndClose}
              >
                トップページへ戻る
              </button>
            </div>
          ) : (
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label className="form-label" htmlFor="res-name">
                  お名前 <span className="required-mark">*</span>
                </label>
                <input
                  id="res-name"
                  type="text"
                  name="name"
                  required
                  placeholder="例：星野 結衣"
                  className="form-input"
                  value={formValues.name}
                  onChange={handleChange}
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label className="form-label" htmlFor="res-tel">
                    お電話番号 <span className="required-mark">*</span>
                  </label>
                  <input
                    id="res-tel"
                    type="tel"
                    name="tel"
                    required
                    placeholder="例：090-1234-5678"
                    className="form-input"
                    value={formValues.tel}
                    onChange={handleChange}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label" htmlFor="res-email">
                    メールアドレス <span className="required-mark">*</span>
                  </label>
                  <input
                    id="res-email"
                    type="email"
                    name="email"
                    required
                    placeholder="example@etoile.jp"
                    className="form-input"
                    value={formValues.email}
                    onChange={handleChange}
                  />
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label className="form-label" htmlFor="res-date">
                    ご来店希望日 <span className="required-mark">*</span>
                  </label>
                  <input
                    id="res-date"
                    type="date"
                    name="date"
                    required
                    min={today}
                    className="form-input"
                    value={formValues.date}
                    onChange={handleChange}
                  />
                </div>
                <div className="form-group">
                  <label className="form-label" htmlFor="res-time">
                    ご来店希望時間 <span className="required-mark">*</span>
                  </label>
                  <select
                    id="res-time"
                    name="time"
                    className="form-select"
                    value={formValues.time}
                    onChange={handleChange}
                  >
                    <option value="09:00">09:00 (モーニング)</option>
                    <option value="10:00">10:00</option>
                    <option value="11:30">11:30 (ランチ)</option>
                    <option value="13:00">13:00</option>
                    <option value="14:00">14:00 (カフェタイム)</option>
                    <option value="15:30">15:30</option>
                    <option value="17:00">17:00</option>
                    <option value="18:30">18:30 (ディナー)</option>
                  </select>
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label className="form-label" htmlFor="res-guests">
                    ご利用人数
                  </label>
                  <select
                    id="res-guests"
                    name="guests"
                    className="form-select"
                    value={formValues.guests}
                    onChange={handleChange}
                  >
                    <option value={1}>1名様</option>
                    <option value={2}>2名様</option>
                    <option value={3}>3名様</option>
                    <option value={4}>4名様</option>
                    <option value={5}>5名様</option>
                    <option value={6}>6名様</option>
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label" htmlFor="res-seating">
                    ご希望のお席
                  </label>
                  <select
                    id="res-seating"
                    name="seatingPreference"
                    className="form-select"
                    value={formValues.seatingPreference}
                    onChange={handleChange}
                  >
                    <option value="table">テーブル席</option>
                    <option value="counter">カウンター席</option>
                    <option value="terrace">テラス席 (ペット可)</option>
                  </select>
                </div>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="res-note">
                  ご要望・アレルギー・記念日のお祝いなど
                </label>
                <textarea
                  id="res-note"
                  name="note"
                  rows={3}
                  className="form-textarea"
                  placeholder="バースデープレート希望、ベビーカー利用、アレルギー情報などございましたらお気軽にご記入ください。"
                  value={formValues.note}
                  onChange={handleChange}
                />
              </div>

              <button type="submit" className="form-submit-btn">
                予約リクエストを送信する
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default ReservationModal;
